// Colour math: sRGB → D65 Lab; CIEDE2000, kL=kC=kH=1 (Sharma/Wu/Dalal, 2005).
import type {Project,StitchObject} from './project';
export type ThreadBrand=typeof threadBrands[number]['id'];
export type CatalogueThread={readonly code:string;readonly name:string;readonly color:string};
// A thread reference stored on objects: brand id, spool code and the chart's name ('' when unnamed).
export type Thread={brand:string;code:string;name:string};
type Lab=readonly [number,number,number];
export const defaultBrand:ThreadBrand='brother';
const brands=new Map<string,typeof threadBrands[number]>(threadBrands.map(b=>[b.id,b]));
export const brandLabel=(id:string)=>brands.get(id)?.label??id;
export const isThreadBrand=(id:unknown):id is ThreadBrand=>typeof id==='string'&&brands.has(id);
export const threadReference=(t:CatalogueThread,brand:string=defaultBrand):Thread=>({brand,code:t.code,name:t.name});
export const sameThread=(a?:Thread,b?:Thread)=>a?.brand===b?.brand&&a?.code===b?.code;
// Only the inline Brother chart is checked colour-for-colour; other charts are fetched on demand,
// so their references are checked for shape and a known brand.
export function validThread(value:unknown,color:string):value is Thread {
  if(typeof color!=='string'||!value||typeof value!=='object')return false;const t=value as Thread;
  if(!isThreadBrand(t.brand)||typeof t.code!=='string'||!t.code||t.code.length>24||typeof t.name!=='string'||t.name.length>60)return false;
  return t.brand!==defaultBrand||brotherThreads.some(b=>b.code===t.code&&b.name===t.name&&b.color===color.toLowerCase());
}
const charts=new Map<string,Promise<readonly CatalogueThread[]>>([[defaultBrand,Promise.resolve(brotherThreads)]]);
// Brand charts are static files of [code, name, #rrggbb] rows.
export function loadThreads(brand:string):Promise<readonly CatalogueThread[]> {
  let chart=charts.get(brand);
  if(!chart){
    chart=fetch(`/threads/${encodeURIComponent(brand)}.json`).then(r=>{if(!r.ok)throw new Error(String(r.status));return r.json();}).then((rows:[string,string,string][])=>rows.map(([code,name,color])=>({code,name,color})));
    chart.catch(()=>charts.delete(brand));charts.set(brand,chart);
  }
  return chart;
}
export function rgbToLab(color:string):Lab {
  const [r,g,b]=[1,3,5].map(i=>{const v=parseInt(color.slice(i,i+2),16)/255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;});
  const f=(v:number)=>v>216/24389?Math.cbrt(v):(24389/27*v+16)/116;
  const x=f((.4124564*r+.3575761*g+.1804375*b)/.95047),y=f(.2126729*r+.7151522*g+.072175*b),z=f((.0193339*r+.119192*g+.9503041*b)/1.08883);
  return [116*y-16,500*(x-y),200*(y-z)];
}
export function deltaE2000([l1,a1,b1]:Lab,[l2,a2,b2]:Lab):number {
  const rad=Math.PI/180,sin=(v:number)=>Math.sin(v*rad),cos=(v:number)=>Math.cos(v*rad);
  const c=(Math.hypot(a1,b1)+Math.hypot(a2,b2))/2,g=.5*(1-Math.sqrt(c**7/(c**7+25**7)));
  const ap1=(1+g)*a1,ap2=(1+g)*a2,c1=Math.hypot(ap1,b1),c2=Math.hypot(ap2,b2);
  const hue=(a:number,b:number)=>a===0&&b===0?0:(Math.atan2(b,a)/rad+360)%360,h1=hue(ap1,b1),h2=hue(ap2,b2);
  let dh=h2-h1;if(c1*c2===0)dh=0;else if(dh>180)dh-=360;else if(dh< -180)dh+=360;
  const dl=l2-l1,dc=c2-c1,dH=2*Math.sqrt(c1*c2)*sin(dh/2),lm=(l1+l2)/2,cm=(c1+c2)/2;
  const hm=c1*c2===0?h1+h2:Math.abs(h1-h2)<=180?(h1+h2)/2:(h1+h2+(h1+h2<360?360:-360))/2;
  const t=1-.17*cos(hm-30)+.24*cos(2*hm)+.32*cos(3*hm+6)-.20*cos(4*hm-63);
  const sl=1+.015*(lm-50)**2/Math.sqrt(20+(lm-50)**2),sc=1+.045*cm,sh=1+.015*cm*t;
  const rt=-2*Math.sqrt(cm**7/(cm**7+25**7))*sin(60*Math.exp(-(((hm-275)/25)**2)));
  return Math.sqrt((dl/sl)**2+(dc/sc)**2+(dH/sh)**2+rt*(dc/sc)*(dH/sh));
}
const labCache=new WeakMap<readonly CatalogueThread[],Lab[]>();
export function nearestThread<T extends CatalogueThread>(color:string,threads:readonly T[]):T {
  let labs=labCache.get(threads);if(!labs){labs=threads.map(t=>rgbToLab(t.color));labCache.set(threads,labs);}
  const lab=rgbToLab(color);let best=0,distance=Infinity;
  labs.forEach((l,i)=>{const d=deltaE2000(lab,l);if(d<distance){distance=d;best=i;}});return threads[best];
}
export const nearestBrother=(color:string)=>nearestThread(color,brotherThreads);
export function recolorObject(o:StitchObject,color:string,thread?:Thread):StitchObject {
  const next={...o,color};delete next.thread;if(thread)next.thread=thread;return next;
}
// Selection and whole-design actions return one project for the editor's single commit/undo step.
export function applyThread(p:Project,ids:readonly string[],color:string,thread?:Thread):Project {
  return {...p,objects:p.objects.map(o=>ids.includes(o.id)?recolorObject(o,color,thread):o)};
}
// Snap every (or each selected) object and text border to the nearest thread of one chart.
export function matchThreads(p:Project,threads:readonly CatalogueThread[],brand:string,ids?:readonly string[]):Project {
  const near=(color:string)=>{const t=nearestThread(color,threads);return {color:t.color,thread:threadReference(t,brand)};};
  return {...p,objects:p.objects.map(o=>{if(ids&&!ids.includes(o.id))return o;const m=near(o.color),next=recolorObject(o,m.color,m.thread);if(o.text?.border){const b=near(o.text.border.color);next.text={...o.text,border:{...o.text.border,...b}};}return next;})};
}
/** @test */ export const matchBrother=(p:Project,ids?:readonly string[])=>matchThreads(p,brotherThreads,defaultBrand,ids);
// Palette order: chromatic threads by hue (red first), light to dark within each hue; neutrals last.
export function paletteOrder<T extends CatalogueThread>(threads:readonly T[]):T[] {
  const key=threads.map(t=>{const [l,a,b]=rgbToLab(t.color),chroma=Math.hypot(a,b),hue=((Math.atan2(b,a)*180/Math.PI)+340)%360;
    return {t,neutral:chroma<10,band:Math.floor(hue/24),l};});
  return key.sort((x,y)=>Number(x.neutral)-Number(y.neutral)||(x.neutral?0:x.band-y.band)||y.l-x.l).map(k=>k.t);
}
// Every object sews with a catalogue thread: new objects default to Brother 100 Black.
const black=brotherThreads.find(t=>t.code==='100')!;
export const defaultThread:Thread=threadReference(black),defaultThreadColour:string=black.color;
// Snap objects and text borders that have no thread (imports, demo, agent colours) to the nearest
// Brother thread. Returns the same project when nothing changes so commits stay cheap.
export function ensureThreads(p:Project):Project {
  const missing=(o:StitchObject)=>!o.thread||!!o.text?.border&&!o.text.border.thread;
  if(!p.objects.some(missing))return p;
  const snap=(color:string)=>{const t=nearestBrother(color);return {color:t.color,thread:threadReference(t)};};
  return {...p,objects:p.objects.map(o=>{
    if(!missing(o))return o;let next=o;
    if(!o.thread){const m=snap(o.color);next=recolorObject(o,m.color,m.thread);}
    if(o.text?.border&&!o.text.border.thread)next={...next,text:{...o.text,border:{...o.text.border,...snap(o.text.border.color)}}};
    return next;
  })};
}
